//! Decode Core's contract test vectors with the Controller's own decoders.
//!
//! The vectors are generated by Core from its real IPC handlers
//! (`msst-net-core-31x/crates/msst-ipc-protocol/tests/vectors`, see Core's
//! `contract_tests.rs`).  If Core changes a payload shape, this test fails
//! here instead of the UI silently showing nothing.

use std::path::PathBuf;

use msst_ipc_protocol::{IpcMessage, IpcResponse};
use msst_net_controller::error::{ControllerError, UiError};
use msst_net_controller::state::{ResourceData, StateStore};
use serde_json::Value;

fn vectors_dir() -> PathBuf {
    // The protocol crate is a path dependency next to this repository.
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../msst-net-core-31x/crates/msst-ipc-protocol/tests/vectors")
}

fn vector(name: &str) -> Value {
    let path = vectors_dir().join(format!("{name}.json"));
    serde_json::from_str(&std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))).unwrap()
}

/// The `Ok` data of a vector's response frame.
fn ok_data(name: &str) -> Value {
    match serde_json::from_value::<IpcMessage>(vector(name)["response"].clone()).unwrap() {
        IpcMessage::Response { body: IpcResponse::Ok(v), .. } => v,
        other => panic!("{name}: expected an Ok response, got {other:?}"),
    }
}

async fn store_from_vectors() -> StateStore {
    let store = StateStore::new();
    store.set_protocol_minor(3).await;
    let apply = |d: ResourceData| {
        let store = store.clone();
        async move { assert!(store.apply_resource(0, d).await) }
    };
    apply(ResourceData::health(&ok_data("health")).unwrap()).await;
    apply(ResourceData::room(&ok_data("get_system_state")).unwrap()).await;
    apply(ResourceData::nodes(&ok_data("get_nodes"), Some(&ok_data("get_path_view"))).unwrap()).await;
    apply(ResourceData::acl_rules(&ok_data("get_acl_rules")).unwrap()).await;
    apply(ResourceData::acl_groups(&ok_data("get_acl_groups")).unwrap()).await;
    apply(ResourceData::pending_auth(&ok_data("get_pending_auth"), 1_000).unwrap()).await;
    store
}

#[tokio::test]
async fn query_vectors_decode_into_the_view() {
    let s = store_from_vectors().await.snapshot().await;

    let h = s.health.expect("health");
    assert_eq!(h.status, "ok");
    assert_eq!(h.access_auth_required, Some(false));
    assert_eq!(h.generation, Some(0));
    assert_eq!(h.device_handle, None, "unset strings are null in protocol 0.3");
    assert_eq!(h.ipc_role.as_deref(), Some("admin"), "protocol 0.4 reports the connection's role");
    assert!(!s.access_auth_required);

    assert_eq!(s.room.room_id.as_deref(), Some("space-1"));
    assert_eq!(s.room.peers.len(), 2, "room view includes this device");
    assert!(s.room.peers.iter().all(|p| p.ipv4.is_some()));

    let bob = &s.nodes["device-0000000b"];
    assert_eq!(bob.user_handle.as_deref(), Some("bob"));
    assert_eq!(bob.path_mode.as_deref(), Some("relay"));

    assert!(!s.acl_rules.is_empty());
    assert!(s.acl_rules[0].fields.contains_key("permission_group"));
    assert!(!s.acl_groups.is_empty());
    assert_eq!(s.pending_auth[0].expires_at_ms, Some(1_000 + 60_000));
}

#[tokio::test]
async fn event_vectors_apply_without_requery() {
    let store = store_from_vectors().await;
    let events: Vec<Value> = serde_json::from_value(vector("events")).unwrap();
    assert!(!events.is_empty());
    for e in events {
        let body = match serde_json::from_value::<IpcMessage>(e).unwrap() {
            IpcMessage::Event { body, seq } => {
                assert!(seq.is_some(), "protocol 0.4 state events carry seq: {body:?}");
                body
            }
            other => panic!("not an event: {other:?}"),
        };
        let refresh = store.apply_event(&body).await;
        assert!(refresh.is_empty(), "protocol 0.3 event should carry full state, re-query requested: {body:?} → {refresh:?}");
    }
    let s = store.snapshot().await;
    let h = s.health.unwrap();
    assert_eq!(h.device_display_name.as_deref(), Some("Laptop"));
    assert_eq!(h.ping_enabled, Some(true));
    assert_eq!(s.nodes["device-0000000b"].display_name.as_deref(), Some("Bob's new PC"));
    assert_eq!(s.nodes["device-0000000b"].path_mode.as_deref(), Some("relay"), "path mode survives node updates");
    assert_eq!(s.room.room_name.as_deref(), Some("Test room"));
}

#[test]
fn query_vectors_carry_event_seq() {
    for name in ["health", "get_nodes", "get_acl_rules", "get_system_state"] {
        match serde_json::from_value::<IpcMessage>(vector(name)["response"].clone()).unwrap() {
            IpcMessage::Response { event_seq, .. } => assert!(event_seq.is_some(), "{name}: no event_seq"),
            other => panic!("{name}: not a response: {other:?}"),
        }
    }
}

#[test]
fn error_vectors_have_user_messages() {
    for name in ["get_node_not_found", "set_net_settings_invalid", "update_acl_rule_unknown_field"] {
        let e = match serde_json::from_value::<IpcMessage>(vector(name)["response"].clone()).unwrap() {
            IpcMessage::Response { body: IpcResponse::Error(e), .. } => e,
            other => panic!("{name}: expected an error, got {other:?}"),
        };
        let ui = UiError::from(ControllerError::from(e.clone()));
        assert_eq!(ui.code, e.code);
        assert!(!ui.message.contains(&format!("（{}）", e.code)), "{name}: unmapped code {}", e.code);
    }
}

#[test]
fn every_vector_frame_decodes() {
    let mut n = 0;
    for entry in std::fs::read_dir(vectors_dir()).expect("vectors dir (Core repo next to this one)") {
        let path = entry.unwrap().path();
        let v: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        let frames: Vec<Value> = match v {
            Value::Array(events) => events,
            v => vec![v["request"].clone(), v["response"].clone()],
        };
        for f in frames {
            serde_json::from_value::<IpcMessage>(f).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        }
        n += 1;
    }
    assert!(n >= 20, "expected Core's full vector set, found {n}");
}
